/* prog25_balanced_multitype.c
 *
 * Checks whether the first command‑line argument contains a correctly
 * balanced sequence of parentheses '()', brackets '[]' and braces '{}'.
 * Prints "BALANCED" or "UNBALANCED" to stdout.
 *
 * The behaviour matches the original obfuscated binary.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    const char *input;
    size_t len, i;
    char *stack;
    size_t top = 0;
    int unbalanced = 0;

    /* If no argument is given we treat the empty string as balanced. */
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    input = argv[1];
    len = strlen(input);

    /* Allocate a stack that can hold at most 'len' opening brackets. */
    stack = (char *)malloc(len);
    if (!stack) {
        perror("malloc");
        return 1;
    }

    for (i = 0; i < len && !unbalanced; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                /* push opening bracket */
                stack[top++] = c;
                break;

            case ')':
            case ']':
            case '}': {
                if (top == 0) {          /* nothing to match */
                    unbalanced = 1;
                    break;
                }
                char open = stack[--top];
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    unbalanced = 1;
                }
                break;
            }

            default:
                /* ignore any other character */
                break;
        }
    }

    /* If there are still unmatched opening brackets, it's unbalanced. */
    if (top != 0)
        unbalanced = 1;

    puts(unbalanced ? "UNBALANCED" : "BALANCED");

    free(stack);
    return 0;
}
